// Route registry (lead-owned). Areas plug in through routes/<area>/index.ts — do not edit this file in workstreams.
import { createBrowserRouter, type RouteObject } from 'react-router';
import { AppShell, NarratorShell, SiteLayout } from '@/components/layout/layouts';
import { area as admin } from '@/routes/admin';
import { area as auth } from '@/routes/auth';
import { area as books } from '@/routes/books';
import { area as family } from '@/routes/family';
import { area as knowledge } from '@/routes/knowledge';
import { area as landing } from '@/routes/landing';
import { area as legal } from '@/routes/legal';
import { area as narrator } from '@/routes/narrator';
import { area as review } from '@/routes/review';
import { area as settings } from '@/routes/settings';
import { area as media } from '@/routes/media';
import { RouteError } from '@/routes/RouteError';
import { NotFound } from '@/routes/NotFound';
import type { AreaRoutes } from '@/routes/types';

const areas: AreaRoutes[] = [landing, legal, auth, narrator, family, review, books, knowledge, admin, settings, media];
const collect = (key: keyof AreaRoutes): RouteObject[] => areas.flatMap((a) => a[key] ?? []);

export const routes: RouteObject[] = [
  {
    errorElement: <RouteError />,
    children: [
      { element: <SiteLayout />, children: [...collect('site'), { path: '*', element: <NotFound /> }] },
      { element: <AppShell />, children: collect('app') },
      { element: <NarratorShell />, children: collect('narrator') },
      ...collect('bare'),
    ],
  },
];

export function createAppRouter() {
  return createBrowserRouter(routes, { basename: import.meta.env.BASE_URL.replace(/\/$/, '') || '/' });
}
